const AlchemystAI = require('@alchemystai/sdk');

async function test() {
  const apiKey = process.env.ALCHEMYST_AI_API_KEY;
  if (!apiKey) {
    console.error("No API key found!");
    return;
  }
  const client = new AlchemystAI({ apiKey });

  const sessionId = 'test-cli-session-' + Math.random().toString(36).substring(7);
  const userId = 'test-user-alice';

  console.log("Adding memory...");
  try {
    const addRes = await client.v1.context.add({
      context_type: 'conversation',
      documents: [{ content: 'Alice loves coding in TypeScript' }],
      scope: 'internal',
      source: 'test-script',
      metadata: {
        groupName: [sessionId, userId],
        fileName: 'test.txt',
        fileType: 'text/plain',
        fileSize: 100,
        lastModified: new Date().toISOString()
      }
    });
    console.log("Add response:", JSON.stringify(addRes, null, 2));
  } catch (err) {
    console.error("Add error:", err);
  }

  // Wait a few seconds for indexing, as memory indexing can be asynchronous
  console.log("Waiting 3 seconds for indexing...");
  await new Promise(resolve => setTimeout(resolve, 3000));

  console.log("Searching memory with group_name...");
  try {
    const searchRes = await client.v1.context.search({
      query: 'TypeScript',
      similarity_threshold: 0.1,
      minimum_similarity_threshold: 0.1,
      scope: 'internal',
      body_metadata: {
        group_name: [sessionId]
      }
    });
    console.log("Search response:", JSON.stringify(searchRes, null, 2));
  } catch (err) {
    console.error("Search error:", err);
  }
}

test();

